`timescale 1ns/1ps
// Generated by hls from examples/reassign/reassign.txt, casap schedule.
// Each op, its steps and its unit:
//   X_1 = A_0 + B_0  step 1, add0
//   A_1 = A_0 + A_0  step 1, add1
//   X_2 = X_1 * A_1  steps 2-3, mul0
//   Y_1 = X_2 - B_0  step 4, sub0
module hls_core (
    input             clk,
    input             rst,
    input             step,
    /* verilator lint_off UNUSED */
    input      [11:0] sw,      // input slots: A_0 = SW11-8, B_0 = SW7-4, SW3-0 unused
    /* verilator lint_on UNUSED */
    input      [5:0]  code,    // observe code
    output reg [15:0] value,
    output reg        valid,   // 0 = show ----
    output reg [7:0]  state,   // 0 = IDLE, 1-4 = steps, 5 = DONE
    output            done
);
    localparam DONE = 8'd5;

    reg [15:0] A_0, B_0, X_1, A_1, X_2, Y_1;

    // FSM outputs.
    reg add0_busy, add1_busy, sub0_busy, mul0_busy;
    reg X_1_we, A_1_we, X_2_we, Y_1_we;

    // Units and their input muxes.
    wire [15:0] add0_y, add1_y, sub0_y, mul0_y;

    adder      add0 (.a(A_0), .b(B_0), .y(add0_y));
    adder      add1 (.a(A_0), .b(A_0), .y(add1_y));
    subtractor sub0 (.a(X_2), .b(B_0), .y(sub0_y));
    multiplier mul0 (.a(X_1), .b(A_1), .y(mul0_y));

    // Sequencer: one state per step pulse, stopping at DONE.
    always @(posedge clk)
        if (rst) state <= 8'd0;
        else if (step && state != DONE) state <= state + 8'd1;

    assign done = (state == DONE);

    // Moore outputs: each step's mux selects, busy units and register writes.
    always @* begin
        add0_busy = 1'b0; add1_busy = 1'b0; sub0_busy = 1'b0; mul0_busy = 1'b0; X_1_we = 1'b0;
        A_1_we = 1'b0; X_2_we = 1'b0; Y_1_we = 1'b0;
        case (state)
            8'd1: begin
                add0_busy = 1'b1; add1_busy = 1'b1; X_1_we = 1'b1; A_1_we = 1'b1;
            end
            8'd2: begin
                mul0_busy = 1'b1;
            end
            8'd3: begin
                mul0_busy = 1'b1; X_2_we = 1'b1;
            end
            8'd4: begin
                sub0_busy = 1'b1; Y_1_we = 1'b1;
            end
            default: ;
        endcase
    end

    // Inputs follow the switches in IDLE; results are written on the step pulse that ends their step.
    always @(posedge clk)
        if (rst) begin
            A_0 <= 16'd0; B_0 <= 16'd0; X_1 <= 16'd0; A_1 <= 16'd0; X_2 <= 16'd0; Y_1 <= 16'd0;
        end else begin
            if (state == 8'd0) begin
                A_0 <= {12'd0, sw[11:8]};
                B_0 <= {12'd0, sw[7:4]};
            end
            if (step && X_1_we) X_1 <= add0_y;
            if (step && A_1_we) A_1 <= add1_y;
            if (step && X_2_we) X_2 <= mul0_y;
            if (step && Y_1_we) Y_1 <= sub0_y;
        end

    // Observe codes: units, then results in equation order, then inputs.
    always @* begin
        value = 16'd0; valid = 1'b0;
        case (code)
            6'd0: begin value = add0_y; valid = add0_busy; end
            6'd1: begin value = add1_y; valid = add1_busy; end
            6'd2: begin value = sub0_y; valid = sub0_busy; end
            6'd3: begin value = mul0_y; valid = mul0_busy; end
            6'd4: begin value = X_1; valid = state > 8'd1; end
            6'd5: begin value = A_1; valid = state > 8'd1; end
            6'd6: begin value = X_2; valid = state > 8'd3; end
            6'd7: begin value = Y_1; valid = state > 8'd4; end
            6'd8: begin value = A_0; valid = 1'b1; end
            6'd9: begin value = B_0; valid = 1'b1; end
            default: ;
        endcase
    end
endmodule
